<script>
  (function () {
    function currentLocale() {
      var locale = '';
      if (window.Shopify && typeof window.Shopify.locale === 'string') {
        locale = window.Shopify.locale;
      } else if (document.documentElement && document.documentElement.lang) {
        locale = document.documentElement.lang;
      }
      return String(locale || '').replace('_', '-').trim();
    }

    function localeCopy() {
      var copyMap = window.DLM_PRODUCT_PAGE_COPY;
      if (!copyMap || typeof copyMap !== 'object') return null;

      var locale = currentLocale().toLowerCase();
      var root = locale.split('-')[0];
      var candidates = [locale];
      if (root && root !== locale) candidates.push(root);
      if (root === 'pt') candidates.push('pt-BR', 'pt-PT');
      if (root === 'ro') candidates.push('ro', 'ro-RO');
      if (root === 'no') candidates.push('no', 'nb');

      var keys = Object.keys(copyMap);
      for (var i = 0; i < candidates.length; i += 1) {
        var candidate = candidates[i];
        for (var j = 0; j < keys.length; j += 1) {
          if (keys[j].toLowerCase() === candidate.toLowerCase()) {
            return copyMap[keys[j]];
          }
        }
      }

      return copyMap.en || null;
    }

    var copy = localeCopy();
    if (!copy) return;
    var desktopUxWrapper = document.querySelector('[data-product-desktop-ux]');
    var isGoldenDaisyPdp = desktopUxWrapper && desktopUxWrapper.getAttribute('data-product-handle') === 'golden-daisy-mommy-and-me-set';
    var localeRoot = currentLocale().toLowerCase().split('-')[0];
    var customerPhotosByLocale = {
      cs: 'Fotky zákazníků',
      da: 'Kundebilleder',
      de: 'Kundenfotos',
      el: 'Φωτογραφίες πελατών',
      es: 'Fotos de clientes',
      fr: 'Photos clients',
      it: 'Foto dei clienti',
      nl: "Foto's van klanten",
      pl: 'Zdjęcia klientów',
      pt: 'Fotos de clientes',
      ro: 'Fotografii de la clienți',
      sv: 'Kundfoton'
    };
    var customerPhotosHeading = copy.customer_photos_heading || customerPhotosByLocale[localeRoot] || 'Customer photos';
    var matchingSetRuntimeCopy = copy.matching_set_copy;
    if (isGoldenDaisyPdp && (!localeRoot || localeRoot === 'en')) {
      matchingSetRuntimeCopy = 'Pair the yellow daisy top with the ivory floral pants for a complete mommy-and-me outfit.';
    }

    var translations = {
      'Build your matching set': copy.matching_set_heading,
      ['Choose the family sizes you want and add them together from one product page.']: matchingSetRuntimeCopy,
      ['Add one piece per family member. Sizes are independent and each piece is sold separately.']: matchingSetRuntimeCopy,
      // CRO Tier 1 (May 2026): new conversion-friendly EN default — must
      // still get swapped to the localized matching_set_copy for non-EN
      // shoppers, so we add it as another runtime translation key.
      ['Add matching family sizes below — each selection is sold separately.']: matchingSetRuntimeCopy,
      ['Pair the yellow daisy top with the ivory floral pants for a complete mommy-and-me outfit.']: matchingSetRuntimeCopy,
      ['Choose at least one family size to add your set.']: copy.matching_set_empty,
      ['Choose at least one size to add your set.']: copy.matching_set_empty,
      'Add selected pieces': copy.matching_set_add,
      'Add selected pieces to cart': copy.matching_set_add,
      'Add matching pieces': copy.matching_set_add,
      'Add matching pieces to cart': copy.matching_set_add,
      // CRO redesign May 2026: new bundle CTA copy.
      'Add Matching Set to Cart': copy.matching_set_add,
      'Compare family sizes': copy.grouped_size_guide_label,
      'Compare all sizes': copy.compare_size_guide_label,
      'Size guide & fit': copy.single_size_guide_label,
      'Your size details': copy.selected_size_guide_label,
      'Open the full chart below to compare nearby sizes.': copy.size_guide_compare_hint,
      'Customer reviews': copy.reviews_heading,
      'Customer photo reviews': copy.photo_heading,
      'Customer photos': customerPhotosHeading,
      'Jump to reviews': copy.jump_to_reviews,
      'Secure Checkout': copy.secure_checkout,
      ['30-Day ' + 'Returns']: copy.returns,
      ['Trusted ' + 'since 2016']: copy.trusted_since,
      'Need help? We typically reply within one business day.': copy.assistance_note,
      ['Shipping ' + 'Worldwide']: copy.shipping_title,
      'Shipping options': copy.free_shipping_label,
      'Est. Delivery': copy.estimated_delivery,
      'Delivery details at checkout': copy.estimated_delivery,
      'Want it faster? Spend $100+ and get': copy.faster_shipping_prefix,
      'Express shipping': copy.free_premium_shipping,
      'Standard shipping included': copy.free_shipping_all_orders,
      'Return Policy': copy.return_policy_title,
      ['We gladly accept returns within 30 days of ' + 'purchase.']: copy.return_policy_line_1,
      ['Items should be in their original condition and packaging to qualify for a full refund. Please note that buyers are responsible for return shipping costs.']: copy.return_policy_line_2,
      ["If an item is returned damaged, used, or missing parts, we may deduct a portion of the refund to cover any loss in the item's value."]: copy.return_policy_line_3,
      ['To ensure a smooth return process, kindly return items in the same condition as received, including all packaging and original contents.']: copy.return_policy_line_4,
      'Shopping Security': copy.shopping_security_title,
      'Safe Payment Options': copy.safe_payment_options_title,
      'We accept all major credit and debit cards. Your card details are secure and never shared with our partners. You can easily manage your saved cards anytime. For any transaction inquiries, please contact your card issuer.': copy.safe_payment_description,
      'Shipping Support': copy.secure_logistics_title,
      'If a package is damaged or lost in transit, contact us so we can help review the shipment.': copy.secure_logistics_line_1,
      'Use your order tracking link for the latest carrier updates.': copy.secure_logistics_line_2,
      'Secure Privacy': copy.secure_privacy_title,
      'Protecting your privacy is important to us! Please be assured that your information will be kept secured and uncompromised. We do not sell your personal information for money and will only use your information in accordance with our privacy and cookie policy to provide and improve our services to you.': copy.secure_privacy_description,
      'Complete the Look': copy.complete_the_look,
      'Similar styles': copy.similar_styles,
      'Browse similar styles': copy.browse_similar_styles,
      'Use this collection to compare a few close matches before you go back to shopping.': copy.compare_collection_copy,
      'Popular with Families': copy.popular_with_families,
      'Recently Viewed': copy.recently_viewed,
      'CUSTOMER REVIEWS': copy.review_widget_heading_uppercase,
      'Customer Reviews': copy.review_widget_heading,
      'Be the first to write a review': copy.review_widget_empty,
      'Write a review': copy.review_widget_write_review,
      'Write a Review': copy.review_widget_write_review_title,
    };

    function normalize(text) {
      return text ? text.replace(/\s+/g, ' ').trim() : '';
    }

    function replaceWithContext(template, context) {
      return String(template || '').replace(/__CONTEXT__/g, function () { return context || ''; });
    }

    function translateTextNodes(root) {
      if (!root) return;
      var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
      var node;
      while ((node = walker.nextNode())) {
        var normalized = normalize(node.nodeValue);
        if (!normalized) continue;
        if (Object.prototype.hasOwnProperty.call(translations, normalized)) {
          node.nodeValue = node.nodeValue.replace(normalized, translations[normalized]);
        }
      }
    }

    function applyAttributeTranslations() {
      var wrapper = desktopUxWrapper || document.querySelector('[data-product-desktop-ux]');
      if (wrapper) {
        wrapper.setAttribute('data-matching-set-copy', matchingSetRuntimeCopy);
        wrapper.setAttribute('data-matching-set-empty', copy.matching_set_empty);
        wrapper.setAttribute('data-matching-set-add', copy.matching_set_add);
        wrapper.setAttribute('data-matching-set-success', copy.matching_set_success);
        wrapper.setAttribute('data-matching-set-error', copy.matching_set_error);
        wrapper.setAttribute('data-size-guide-single-label', copy.single_size_guide_label);
        wrapper.setAttribute('data-size-guide-grouped-label', copy.grouped_size_guide_label);
        wrapper.setAttribute('data-size-guide-compare-label', copy.compare_size_guide_label);
        wrapper.setAttribute('data-size-guide-selected-label', copy.selected_size_guide_label);
        wrapper.setAttribute('data-size-guide-compare-hint', copy.size_guide_compare_hint);
        wrapper.setAttribute('data-size-guide-unit-toggle-label', copy.size_guide_unit_toggle_label);
        wrapper.setAttribute('data-customer-photos-label', customerPhotosHeading);
      }

      document.querySelectorAll('[data-back-to-results]').forEach(function (control) {
        control.setAttribute('data-back-to-results-label-default', copy.back_to_results);
        control.setAttribute('data-back-to-results-template', copy.back_to_context);
        control.setAttribute('data-back-to-search-results-label', copy.back_to_search_results);
      });

      document.querySelectorAll('.product__trust-strip').forEach(function (strip) {
        strip.setAttribute('aria-label', copy.secure_checkout);
      });
    }

    function applyContextTranslations() {
      document.querySelectorAll('[data-back-to-results-label]').forEach(function (node) {
        var text = normalize(node.textContent);
        if (text === 'Back to results') {
          node.textContent = copy.back_to_results;
          return;
        }
        if (text === 'Back to Family Sets') {
          node.textContent = copy.back_to_family_sets;
          return;
        }
        if (text.indexOf('Back to ') === 0) {
          node.textContent = replaceWithContext(copy.back_to_context, text.slice('Back to '.length));
        }
      });

      document.querySelectorAll('.buy-box-similar-styles__title').forEach(function (node) {
        var text = normalize(node.textContent);
        if (text === 'Browse similar styles') {
          node.textContent = copy.browse_similar_styles;
          return;
        }
        if (text.indexOf('Browse more from ') === 0) {
          node.textContent = replaceWithContext(copy.browse_more_from, text.slice('Browse more from '.length));
        }
      });

      document.querySelectorAll('.product-breadcrumb__browse-link').forEach(function (link) {
        var text = normalize(link.textContent);
        if (text === 'View similar styles') {
          link.textContent = copy.view_similar_styles;
        }

        ['aria-label', 'title'].forEach(function (attribute) {
          var value = normalize(link.getAttribute(attribute));
          if (!value) return;
          if (value.indexOf('View similar styles in ') === 0) {
            link.setAttribute(attribute, replaceWithContext(copy.view_similar_styles_in, value.slice('View similar styles in '.length)));
          } else if (value === 'View similar styles') {
            link.setAttribute(attribute, copy.view_similar_styles);
          }
        });
      });
    }

    function applyProductTranslations() {
      applyAttributeTranslations();
      translateTextNodes(document.body);
      applyContextTranslations();

      document.querySelectorAll('[class*="jdgm"]').forEach(function (element) {
        translateTextNodes(element);
      });
    }

    var scheduled = false;
    function scheduleApply() {
      if (scheduled) return;
      scheduled = true;
      window.requestAnimationFrame(function () {
        scheduled = false;
        applyProductTranslations();
      });
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', scheduleApply);
    } else {
      scheduleApply();
    }

    var observer = new MutationObserver(scheduleApply);
    observer.observe(document.body, {
      childList: true,
      subtree: true,
      characterData: true,
    });
  })();
</script>


